@@ -0,0 +1,28 @@
+export interface FormatOptions {
+  locale?: string;
+  includeTime?: boolean;
+}
+
+var defaultOptions: FormatOptions = {
+  locale: "en-US",
+  includeTime: false,
+};
+
+export function formatDate(date: Date, options?: FormatOptions): string {
+  var opts = { ...defaultOptions, ...options };
+
+  if (!(date instanceof Date) || isNaN(date.getTime())) {
+    return "Invalid date";
+  }
+
+  var formatConfig: Intl.DateTimeFormatOptions = {
+    year: "numeric",
+    month: "short",
+    day: "numeric",
+  };
+
+  if (opts.includeTime) {
+    formatConfig.hour = "2-digit";
+    formatConfig.minute = "2-digit";
+  }
+
+  return new Intl.DateTimeFormat(opts.locale, formatConfig).format(date);
+}
